/* Offer Ready: CS fundamentals, SQL practice data. Generated by running every reference query in SQLite
   (3.42.0) and pasting its real output into `expected`. Tables are shared by the exercises that list them. */
OR.csSql = {
  tables: {
    departments: {
      ddl: "CREATE TABLE departments (id INTEGER PRIMARY KEY, name TEXT NOT NULL)",
      cols: ["id", "name"],
      rows: [
        ["1", "Engineering"],
        ["2", "Sales"],
        ["3", "Marketing"],
        ["4", "Legal"]
      ]
    },
    employees: {
      ddl: "CREATE TABLE employees (id INTEGER PRIMARY KEY, name TEXT NOT NULL, dept_id INTEGER REFERENCES departments(id), manager_id INTEGER REFERENCES employees(id), salary INTEGER NOT NULL, hired TEXT NOT NULL)",
      cols: ["id", "name", "dept_id", "manager_id", "salary", "hired"],
      rows: [
        ["1", "Ava", "1", null, "150000", "2019-03-01"],
        ["2", "Ben", "1", "1", "120000", "2020-06-15"],
        ["3", "Cleo", "1", "1", "120000", "2021-01-10"],
        ["4", "Dev", "2", "1", "90000", "2020-09-01"],
        ["5", "Eli", "2", "4", "95000", "2022-02-14"],
        ["6", "Fay", "3", "1", "70000", "2021-07-19"],
        ["7", "Gus", "3", "6", "65000", "2023-05-30"],
        ["8", "Hana", null, "2", "80000", "2022-11-05"],
        ["9", "Ivan", "2", "4", "92000", "2023-01-23"]
      ]
    },
    customers: {
      ddl: "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL)",
      cols: ["id", "name", "city"],
      rows: [
        ["1", "Asha", "Austin"],
        ["2", "Bo", "Boston"],
        ["3", "Cruz", "Austin"],
        ["4", "Dani", "Denver"]
      ]
    },
    orders: {
      ddl: "CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), order_date TEXT NOT NULL, amount REAL, status TEXT)",
      cols: ["id", "customer_id", "order_date", "amount", "status"],
      rows: [
        ["101", "1", "2024-01-05", "50.0", "paid"],
        ["102", "1", "2024-01-20", "30.0", "paid"],
        ["103", "1", "2024-02-11", "120.0", "refunded"],
        ["104", "2", "2024-01-15", "75.5", "paid"],
        ["105", "2", "2024-02-02", null, "pending"],
        ["106", "3", "2024-02-20", "200.0", "paid"],
        ["107", "3", "2024-03-03", "40.0", null],
        ["108", "1", "2024-03-12", "60.0", "paid"],
        ["109", "2", "2024-03-18", "25.0", "paid"]
      ]
    }
  },
  exercises: [
    {
      id: "inner-join",
      title: "Employees with their department",
      level: "Core",
      tables: ["employees", "departments"],
      q: "List each employee's name with the name of their department, for employees that have a department. Sort by employee name.",
      solution: `SELECT e.name AS employee, d.name AS department
FROM employees e
JOIN departments d ON d.id = e.dept_id
ORDER BY e.name;`,
      note: "An inner join keeps only matching pairs, so Hana (`dept_id` is NULL) disappears: NULL never equals anything, including another NULL. Legal has no employees, so it disappears too.",
      expected: {
        cols: ["employee", "department"],
        rows: [
          ["Ava", "Engineering"],
          ["Ben", "Engineering"],
          ["Cleo", "Engineering"],
          ["Dev", "Sales"],
          ["Eli", "Sales"],
          ["Fay", "Marketing"],
          ["Gus", "Marketing"],
          ["Ivan", "Sales"]
        ]
      }
    },
    {
      id: "left-count",
      title: "Headcount per department, including empty ones",
      level: "Core",
      tables: ["departments", "employees"],
      q: "For every department, show its name and how many employees it has. Departments with no employees must appear with 0. Sort by department name.",
      solution: `SELECT d.name AS department, COUNT(e.id) AS headcount
FROM departments d
LEFT JOIN employees e ON e.dept_id = d.id
GROUP BY d.id, d.name
ORDER BY d.name;`,
      note: "The trap is `COUNT(*)`: after the left join, Legal still has one row (all NULL on the employee side), so `COUNT(*)` reports 1. `COUNT(e.id)` counts only non-NULL values, so it reports 0.",
      expected: {
        cols: ["department", "headcount"],
        rows: [
          ["Engineering", "3"],
          ["Legal", "0"],
          ["Marketing", "2"],
          ["Sales", "3"]
        ]
      }
    },
    {
      id: "having",
      title: "Departments with a high average salary",
      level: "Core",
      tables: ["employees", "departments"],
      q: "Show departments whose average salary is above 80000, with the average rounded to the nearest whole number. Sort by average descending.",
      solution: `SELECT d.name AS department, ROUND(AVG(e.salary)) AS avg_salary
FROM employees e
JOIN departments d ON d.id = e.dept_id
GROUP BY d.id, d.name
HAVING AVG(e.salary) > 80000
ORDER BY avg_salary DESC;`,
      note: "`WHERE` filters rows before grouping; `HAVING` filters groups after aggregation. You cannot put `AVG(...)` in `WHERE`. Rounding output is dialect-specific (`ROUND` returns a float in SQLite, so the table shows 130000.0).",
      expected: {
        cols: ["department", "avg_salary"],
        rows: [
          ["Engineering", "130000.0"],
          ["Sales", "92333.0"]
        ]
      }
    },
    {
      id: "anti-join",
      title: "Customers who never ordered",
      level: "Core",
      tables: ["customers", "orders"],
      q: "Return the names of customers who have placed no orders. Sort by name.",
      solution: `SELECT c.name
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id
WHERE o.id IS NULL
ORDER BY c.name;`,
      note: "A left join then `IS NULL` on a column that is never NULL in real rows (the primary key) is the classic anti-join. `NOT EXISTS (SELECT 1 FROM orders WHERE customer_id = c.id)` is equivalent and often reads better.",
      expected: {
        cols: ["name"],
        rows: [
          ["Dani"]
        ]
      }
    },
    {
      id: "null-compare",
      title: "Everyone outside Engineering",
      level: "NULL traps",
      tables: ["employees"],
      q: "List the names of employees who are NOT in department 1 (Engineering). Employees with no department at all must be included. Sort by name.",
      solution: `SELECT name
FROM employees
WHERE dept_id IS NULL OR dept_id <> 1
ORDER BY name;`,
      note: "`dept_id <> 1` is UNKNOWN (not true) when `dept_id` is NULL, and `WHERE` keeps only rows that are TRUE, so the naive query silently drops Hana. Three-valued logic is the source of most NULL bugs. Some dialects offer `IS DISTINCT FROM` for a NULL-safe comparison.",
      expected: {
        cols: ["name"],
        rows: [
          ["Dev"],
          ["Eli"],
          ["Fay"],
          ["Gus"],
          ["Hana"],
          ["Ivan"]
        ]
      }
    },
    {
      id: "not-in-null",
      title: "Departments with nobody in them",
      level: "NULL traps",
      tables: ["departments", "employees"],
      q: "Return the names of departments that have no employees. Sort by name. Hint: one tempting version returns nothing at all.",
      solution: `SELECT d.name
FROM departments d
WHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id)
ORDER BY d.name;`,
      note: "`WHERE d.id NOT IN (SELECT dept_id FROM employees)` returns zero rows here. The subquery's list contains a NULL (Hana), so `d.id NOT IN (..., NULL)` can never be TRUE: for a non-matching id it evaluates to UNKNOWN. `NOT EXISTS` has no such problem. Rule: do not use `NOT IN` over a nullable column.",
      expected: {
        cols: ["name"],
        rows: [
          ["Legal"]
        ]
      }
    },
    {
      id: "self-join",
      title: "Employee and manager side by side",
      level: "Joins",
      tables: ["employees"],
      q: "Show each employee's name and their manager's name. Employees with no manager must appear with a NULL manager. Sort by employee id.",
      solution: `SELECT e.name AS employee, m.name AS manager
FROM employees e
LEFT JOIN employees m ON m.id = e.manager_id
ORDER BY e.id;`,
      note: "A self join is the same table under two aliases. The top of the hierarchy (Ava) has `manager_id` NULL, so it needs a LEFT join, otherwise she vanishes.",
      expected: {
        cols: ["employee", "manager"],
        rows: [
          ["Ava", null],
          ["Ben", "Ava"],
          ["Cleo", "Ava"],
          ["Dev", "Ava"],
          ["Eli", "Dev"],
          ["Fay", "Ava"],
          ["Gus", "Fay"],
          ["Hana", "Ben"],
          ["Ivan", "Dev"]
        ]
      }
    },
    {
      id: "self-join-compare",
      title: "Earning more than your manager",
      level: "Joins",
      tables: ["employees"],
      q: "Find employees who earn more than their own manager. Show employee, their salary, manager, manager's salary. Sort by employee name.",
      solution: `SELECT e.name AS employee, e.salary, m.name AS manager, m.salary AS manager_salary
FROM employees e
JOIN employees m ON m.id = e.manager_id
WHERE e.salary > m.salary
ORDER BY e.name;`,
      note: "Here an inner join is right: no manager means nothing to compare against. The join condition links the two roles; the `WHERE` compares them.",
      expected: {
        cols: ["employee", "salary", "manager", "manager_salary"],
        rows: [
          ["Eli", "95000", "Dev", "90000"],
          ["Ivan", "92000", "Dev", "90000"]
        ]
      }
    },
    {
      id: "top-n-per-group",
      title: "Two best-paid people per department",
      level: "Window functions",
      tables: ["employees", "departments"],
      q: "For each department, return its two highest-paid employees (department, name, salary). Break salary ties by earlier hire date. Ignore employees without a department. Sort by department name, then salary descending, then hire date.",
      solution: `SELECT department, name, salary
FROM (
  SELECT d.name AS department, e.name, e.salary, e.hired,
         ROW_NUMBER() OVER (PARTITION BY e.dept_id ORDER BY e.salary DESC, e.hired) AS rn
  FROM employees e
  JOIN departments d ON d.id = e.dept_id
) ranked
WHERE rn <= 2
ORDER BY department, salary DESC, hired;`,
      note: "`ROW_NUMBER` gives every row in the partition a distinct number, so the tie between Ben and Cleo (both 120000) is settled by the second sort key. You cannot filter on a window function in the same `SELECT`'s `WHERE`, hence the wrapping subquery (or CTE).",
      expected: {
        cols: ["department", "name", "salary"],
        rows: [
          ["Engineering", "Ava", "150000"],
          ["Engineering", "Ben", "120000"],
          ["Marketing", "Fay", "70000"],
          ["Marketing", "Gus", "65000"],
          ["Sales", "Eli", "95000"],
          ["Sales", "Ivan", "92000"]
        ]
      }
    },
    {
      id: "rank-vs-dense",
      title: "RANK versus DENSE_RANK",
      level: "Window functions",
      tables: ["employees"],
      q: "Show every employee's name and salary with their company-wide rank by salary (highest first) using both RANK and DENSE_RANK. Sort by salary descending, then name.",
      solution: `SELECT name, salary,
       RANK() OVER (ORDER BY salary DESC) AS rnk,
       DENSE_RANK() OVER (ORDER BY salary DESC) AS dense_rnk
FROM employees
ORDER BY salary DESC, name;`,
      note: "After a tie, `RANK` skips numbers (1, 2, 2, 4) while `DENSE_RANK` does not (1, 2, 2, 3). `ROW_NUMBER` would number the tied rows 2 and 3 arbitrarily. Know which one the question wants.",
      expected: {
        cols: ["name", "salary", "rnk", "dense_rnk"],
        rows: [
          ["Ava", "150000", "1", "1"],
          ["Ben", "120000", "2", "2"],
          ["Cleo", "120000", "2", "2"],
          ["Eli", "95000", "4", "3"],
          ["Ivan", "92000", "5", "4"],
          ["Dev", "90000", "6", "5"],
          ["Hana", "80000", "7", "6"],
          ["Fay", "70000", "8", "7"],
          ["Gus", "65000", "9", "8"]
        ]
      }
    },
    {
      id: "nth-highest",
      title: "Third-highest distinct salary",
      level: "Window functions",
      tables: ["employees"],
      q: "Return the third-highest distinct salary in the company as a single column named salary. (If there were fewer than three distinct salaries, the result should be empty.)",
      solution: `SELECT salary
FROM (
  SELECT DISTINCT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS r
  FROM employees
) t
WHERE r = 3;`,
      note: "Distinct salaries here are 150000, 120000, 95000, ..., so the answer is 95000. `DENSE_RANK` collapses the Ben/Cleo tie so the third value really is the third distinct one. `SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 2` is the shorter alternative. It returns no row when there is no third value; the common interview twist is to return NULL instead, which you get by wrapping it as a scalar subquery: `SELECT (SELECT ... LIMIT 1 OFFSET 2) AS salary`.",
      expected: {
        cols: ["salary"],
        rows: [
          ["95000"]
        ]
      }
    },
    {
      id: "running-total",
      title: "Running total per customer",
      level: "Window functions",
      tables: ["orders"],
      q: "For each customer, list their orders in date order with a running total of the amount. Treat a missing amount as 0. Columns: customer_id, order_date, amount, running_total. Sort by customer_id, order_date.",
      solution: `SELECT customer_id, order_date, amount,
       SUM(COALESCE(amount, 0)) OVER (
         PARTITION BY customer_id
         ORDER BY order_date
         ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS running_total
FROM orders
ORDER BY customer_id, order_date;`,
      note: "Spell out the frame. With only `ORDER BY`, the default frame is `RANGE ... CURRENT ROW`, which treats rows with equal `order_date` as peers and gives them the same total; `ROWS` goes strictly row by row. The aggregate `SUM` ignores NULLs anyway, but `COALESCE` makes the intent explicit.",
      expected: {
        cols: ["customer_id", "order_date", "amount", "running_total"],
        rows: [
          ["1", "2024-01-05", "50.0", "50.0"],
          ["1", "2024-01-20", "30.0", "80.0"],
          ["1", "2024-02-11", "120.0", "200.0"],
          ["1", "2024-03-12", "60.0", "260.0"],
          ["2", "2024-01-15", "75.5", "75.5"],
          ["2", "2024-02-02", null, "75.5"],
          ["2", "2024-03-18", "25.0", "100.5"],
          ["3", "2024-02-20", "200.0", "200.0"],
          ["3", "2024-03-03", "40.0", "240.0"]
        ]
      }
    },
    {
      id: "latest-per-group",
      title: "Most recent order per customer",
      level: "Window functions",
      tables: ["customers", "orders"],
      q: "For each customer that has orders, show the name, the id, date and amount of their most recent order. Sort by customer name.",
      solution: `SELECT name, order_id, order_date, amount
FROM (
  SELECT c.name, o.id AS order_id, o.order_date, o.amount,
         ROW_NUMBER() OVER (PARTITION BY c.id ORDER BY o.order_date DESC, o.id DESC) AS rn
  FROM customers c
  JOIN orders o ON o.customer_id = c.id
) t
WHERE rn = 1
ORDER BY name;`,
      note: "The inner join drops Dani, who has no orders. Add `o.id DESC` as a tiebreaker so two orders on one day still give a single deterministic winner. The older alternative, `WHERE order_date = (SELECT MAX(...) ...)`, returns two rows on a tie.",
      expected: {
        cols: ["name", "order_id", "order_date", "amount"],
        rows: [
          ["Asha", "108", "2024-03-12", "60.0"],
          ["Bo", "109", "2024-03-18", "25.0"],
          ["Cruz", "107", "2024-03-03", "40.0"]
        ]
      }
    },
    {
      id: "lag",
      title: "Month-over-month change",
      level: "Window functions",
      tables: ["orders"],
      q: "Total the amount of paid orders per month (format YYYY-MM) and show the change from the previous month. The first month's change is NULL. Columns: month, total, change. Sort by month.",
      solution: `WITH monthly AS (
  SELECT strftime('%Y-%m', order_date) AS month, SUM(amount) AS total
  FROM orders
  WHERE status = 'paid'
  GROUP BY strftime('%Y-%m', order_date)
)
SELECT month, total, total - LAG(total) OVER (ORDER BY month) AS change
FROM monthly
ORDER BY month;`,
      note: "Aggregate first, then apply `LAG` over the aggregated rows (window functions run after `GROUP BY`). `strftime` is SQLite; PostgreSQL uses `to_char(order_date, 'YYYY-MM')` or `date_trunc('month', ...)`, MySQL `DATE_FORMAT`. Refunded, pending and NULL-status orders are excluded by `status = 'paid'`: a NULL status is not equal to 'paid'.",
      expected: {
        cols: ["month", "total", "change"],
        rows: [
          ["2024-01", "155.5", null],
          ["2024-02", "200.0", "44.5"],
          ["2024-03", "85.0", "-115.0"]
        ]
      }
    },
    {
      id: "conditional-agg",
      title: "Orders summary with conditional counts",
      level: "NULL traps",
      tables: ["customers", "orders"],
      q: "For every customer (including those with no orders) show: name, total number of orders, number of paid orders, and total paid amount (0.0 if none). Sort by name.",
      solution: `SELECT c.name,
       COUNT(o.id) AS orders,
       COUNT(CASE WHEN o.status = 'paid' THEN 1 END) AS paid_orders,
       COALESCE(SUM(CASE WHEN o.status = 'paid' THEN o.amount END), 0.0) AS paid_total
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id
GROUP BY c.id, c.name
ORDER BY c.name;`,
      note: "`CASE` without `ELSE` yields NULL, and `COUNT`/`SUM` skip NULLs, so this pattern counts or sums only the matching rows. For Dani, `SUM` over no non-NULL values is NULL (not 0), so `COALESCE` is needed. Note also that Bo's pending order has a NULL amount, which `SUM` quietly ignores.",
      expected: {
        cols: ["name", "orders", "paid_orders", "paid_total"],
        rows: [
          ["Asha", "4", "3", "140.0"],
          ["Bo", "3", "2", "100.5"],
          ["Cruz", "2", "1", "200.0"],
          ["Dani", "0", "0", "0.0"]
        ]
      }
    }
  ]
};
